const keys = Object.keys(T);
const queue = JSON.parse(
  fs.readFileSync(path.join(__dirname, "he457-queue.json"), "utf8")
);
const missing = Object.keys(queue).filter((k) => !T[k]);
const extra = keys.filter((k) => !queue[k]);
if (missing.length) {
  console.error("Missing translations:", missing);
  process.exit(1);
}
if (extra.length) {
  console.error("Extra keys:", extra);
  process.exit(1);
}

const out = path.join(__dirname, "_hand-en-457.json");
fs.writeFileSync(out, JSON.stringify(T, null, 2) + "\n");
console.log(`Wrote ${keys.length} entries to ${out}`);
